using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BloodySolsticeNextTurnEffect", menuName = "Data/Battle/Effects/Sothis/BloodySolsticeNextTurn Effect")]
public class BloodySolsticeNextTurnEffect : Effect
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		unitEffects.IsEffectActiveRemoveEffect(this, activateFeedback: false);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.4f, delegate
		{
			unitEffects.AddEffect(playerEffectsList.BloodySolsticeActiveEffect, amount);
		});
		return 0;
	}
}
